#include <bits/stdc++.h>
using namespace std;

const int MAXN = 2000;
const int GRID = 12;
const int INF = 1e9;

int dist[GRID][GRID];
int A[GRID][GRID];
int B[GRID][GRID];
vector<int> graph[MAXN];
vector<int> exits[GRID][GRID];

int dr[4] = {0, -1, 0, 1};
int dc[4] = {1, 0, -1, 0};

struct Hungarian {
    int matchCount;
    int matchL[MAXN], matchR[MAXN];
    bool seen[MAXN];

    int solve(int n, vector<int> adj[]) {
        matchCount = 0;
        fill(matchL, matchL + n, -1);
        fill(matchR, matchR + MAXN, -1);
        for (int u = 0; u < n; ++u) {
            fill(seen, seen + MAXN, false);
            if (dfs(u, adj)) ++matchCount;
        }
        return matchCount;
    }

private:
    bool dfs(int u, vector<int> adj[]) {
        for (int v : adj[u]) {
            if (seen[v]) continue;
            seen[v] = true;
            if (matchR[v] == -1 || dfs(matchR[v], adj)) {
                matchL[u] = v;
                matchR[v] = u;
                return true;
            }
        }
        return false;
    }
};

void bfs(int sr, int sc) {
    queue<pair<int, int>> q;
    memset(dist, -1, sizeof(dist));
    q.push({sr, sc});
    dist[sr][sc] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < GRID && nc >= 0 && nc < GRID &&
                A[nr][nc] >= 0 && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1;
                q.push({nr, nc});
            }
        }
    }
}

void bfs_propagate(int sr, int sc, int cnt, int T, int &nodeIdx) {
    int vis[GRID][GRID];
    queue<pair<int, int>> q;
    memset(vis, -1, sizeof(vis));
    q.push({sr, sc});
    vis[sr][sc] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if (vis[r][c] > min(T, dist[r][c])) continue;
        for (int e : exits[r][c]) {
            for (int k = 0; k < cnt; ++k) {
                graph[nodeIdx + k].push_back(e);
            }
        }
        if (vis[r][c] == min(T, dist[r][c])) continue;
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < GRID && nc >= 0 && nc < GRID &&
                A[nr][nc] >= 0 && vis[nr][nc] == -1) {
                vis[nr][nc] = vis[r][c] + 1;
                q.push({nr, nc});
            }
        }
    }
    nodeIdx += cnt;
}

int main() {
    int n, T;
    cin >> n >> T;
    memset(A, -1, sizeof(A));
    memset(B, -1, sizeof(B));
    int sr = -1, sc = -1;

    for (int i = 1; i <= n; ++i) {
        string s;
        getline(cin, s);
        for (int j = 1; j <= n; ++j) {
            char c = cin.get();
            if (isdigit(c)) A[i][j] = c - '0';
            if (c == 'Z') { sr = i; sc = j; }
        }
    }
    cin.ignore();

    bfs(sr, sc);

    for (int i = 1; i <= n; ++i) {
        string s;
        getline(cin, s);
        for (int j = 1; j <= n; ++j) {
            char c = cin.get();
            if (isdigit(c)) B[i][j] = c - '0';
            for (int k = 0; k < B[i][j]; ++k) {
                exits[i][j].push_back((int)exits[i][j].size());
            }
        }
    }
    cin.ignore();

    for (int i = 0; i < GRID; ++i)
        for (int j = 0; j < GRID; ++j)
            if (dist[i][j] == -1) dist[i][j] = INF;

    int nodeCount = 0;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (A[i][j] > 0) bfs_propagate(i, j, A[i][j], T, nodeCount);

    Hungarian solver;
    cout << solver.solve(nodeCount, graph) << '\n';
}
